mapper.select:
SELECT FROM doctor doc INNER JOIN department dept ON dept.id = doc.department_id
AND doc.name LIKE CONCAT('%', #{name}, '%') AND doc.department_id = #{departmentId} AND doc.status = #{status}
ORDER BY doc.sort_order ASC, doc.id ASC

SELECT EXISTS(
    SELECT 1 FROM doctor
    WHERE doctor_code = #{doctorCode}
    AND id != #{excludeId}
)

mapper.update:
UPDATE doctor
SET name = #{doctor.name}, gender = #{doctor.gender}, department_id = #{doctor.departmentId},
    doctor_code = #{doctor.doctorCode}, title = #{doctor.title}, introduction = #{doctor.introduction},
    avatar_url = #{doctor.avatarUrl}, sort_order = #{doctor.sortOrder}
WHERE id = #{doctor.id}
